package com.gamehubstore.inventory_mscv.services;
import com.gamehubstore.inventory_mscv.models.*;import com.gamehubstore.inventory_mscv.repositories.*;import org.junit.jupiter.api.Test;import org.springframework.test.util.ReflectionTestUtils;import java.util.Optional;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class InventorySagaTest {
 @Test void releasingAnUnknownReservationIsAnIdempotentNoOp(){InventoryServiceImpl service=new InventoryServiceImpl();InventoryReservationRepository reservations=mock(InventoryReservationRepository.class);InventoryRepository inventory=mock(InventoryRepository.class);MovimientoInventarioRepository movements=mock(MovimientoInventarioRepository.class);ReflectionTestUtils.setField(service,"reservationRepository",reservations);ReflectionTestUtils.setField(service,"inventoryRepository",inventory);ReflectionTestUtils.setField(service,"movimientoInventarioRepository",movements);when(reservations.findByOrderIdAndProductId(12L,55L)).thenReturn(Optional.empty());assertNull(service.liberarReserva(12L,55L));verifyNoInteractions(inventory,movements);}
 @Test void reserveUsesSameReservationForIdempotentRetry(){InventoryServiceImpl service=new InventoryServiceImpl();InventoryReservationRepository reservations=mock(InventoryReservationRepository.class);InventoryRepository inventory=mock(InventoryRepository.class);MovimientoInventarioRepository movements=mock(MovimientoInventarioRepository.class);ReflectionTestUtils.setField(service,"reservationRepository",reservations);ReflectionTestUtils.setField(service,"inventoryRepository",inventory);ReflectionTestUtils.setField(service,"movimientoInventarioRepository",movements);InventoryReservation prior=new InventoryReservation();prior.setOrderId(12L);prior.setProductId(55L);prior.setQuantity(2L);prior.setStatus("RESERVADA");when(reservations.findByOrderIdAndProductId(12L,55L)).thenReturn(Optional.of(prior));assertSame(prior,service.reservarParaOrden(12L,55L,2L));verifyNoInteractions(inventory,movements);}
}
